def to_base(n, base):
    """Convert a number n to a given base and return its digit representation as a list."""
    if n == 0:
        return [0]
    digits = []
    while n:
        digits.append(int(n % base))
        n //= base
    return digits[::-1]

def from_base(digits, base):
    """Convert a list of digits in a given base to the corresponding number."""
    num = 0
    for digit in digits:
        num = num * base + digit
    return num

